  // Convert both strings to arrays of characters
  let arr1 = Array.from(str1);
  let arr2 = Array.from(str2);

  // Sort the arrays in lexicographic order
  arr1.sort();
  arr2.sort();

  // Convert the sorted arrays back to strings
  let sortedStr1 = arr1.join('');
  let sortedStr2 = arr2.join('');

  // Compare the sorted strings and return the result
  return sortedStr1 === sortedStr2;
}

