    } 
    else if (x < root->key) {
        if (root->left == NULL) {
            Node newNode = new Node;
            newNode->key = x;
            newNode->left = newNode->right = NULL;
            root->left = newNode;
        }
        else {
            root->left = insert(x, root->left);
        }
        // Check if the left subtree is significantly taller than the right subtree
        if (height(root->left) - height(root->right) == 2) {
            // Check if the newly inserted node is in the left subtree
            if (x < root->left->key) {
                root = rotateRight(root); // Perform a single right rotation
            } 
            else {
                root = rotateLeftRight(root); // Perform a left-right rotation
            }
        }
    }
    else {
        if (root->right == NULL) {
            Node newNode = new Node;
            newNode->key = x;
            newNode->left = newNode->right = NULL;
            root->right = newNode;
        }
        else {
            root->right = insert(x, root->right);
        }
        // Check if the right subtree is significantly taller than the left subtree
        if (height(root->right) - height(root->left) == 2) {
            // Check if the newly inserted node is in the right subtree
            if (x > root->right->key) {
                root = rotateLeft(root); // Perform a single left rotation
            } 
            else {
                root = rotateRightLeft(root); // Perform a right-left rotation
            }
        }
    }
    return root; 
}

int height(Node node) {
    if (node == NULL) {
        return -1;
    }
    int leftHeight = height(node->left);
    int rightHeight = height(node->right);
    return max(leftHeight, rightHeight) + 1;
}

Node rotateRight(Node node) {
    Node newRoot = node->left;
    node->left = newRoot->right;
    newRoot->right = node;
    return newRoot;
}

Node rotateLeft(Node node) {
    Node newRoot = node->right;
    node->right = newRoot->left;
    newRoot->left = node;
    return newRoot;
}

Node rotateLeftRight(Node node) {
    node->left = rotateLeft(node->left);
    return rotateRight(node);
}

Node rotateRightLeft(Node node) {
    node->right = rotateRight(node->right);
    return rotateLeft(node);
}"}]

