    "a", "an", "the", "and", "but", "or", "for", "nor", "on", "at", "to", "from", "by"
  ]);

  const words = sentence.split(" ");

  for (let i = 0; i < words.length; i++) {
    let word = words[i];
    let firstLetter = word[0];

    if (i === 0 || !excludedWords.has(word.toLowerCase())) {
