  let prevIsLowerCase = false;

  for (let i = 0; i < camelCase.length; i++) {
    const char = camelCase[i];

    if (char.match(/[A-Z]/)) {
      // Add underscore before the uppercase letter if it's not the first letter or the previous letter is not already an underscore
      if (i !== 0 && !prevIsLowerCase) {
        snakeCase += '_';
      }
      snakeCase += char.toLowerCase();
      prevIsLowerCase = false;
    } else if (char.match(/[a-z0-9_]/)) {
      snakeCase += char;
      prevIsLowerCase = true;
    }
  }

  return snakeCase;
}
```

Here's how you can use this function:

