    return true;
  }

  // Iterate through the string
  for (let i = 0; i < string.length; i++) {
    // If the current character matches the first character of the substring
    if (string[i] === substring[0]) {
      let match = true;

      // Check if the remaining characters of the string match the substring
      for (let j = 1; j < substring.length; j++) {
        if (string[i + j] !== substring[j]) {
          match = false;
          break;
        }
      }

      // If the substring is found, return true
      if (match) {
        return true;
      }
    }
  }

  // If the substring is not found, return false
  return false;
}

console.log(isSubstring("Hello World", "Hello World is a popular phrase")); // true
