function sumOfRange(num) {
  let range = [];
  let previousNum = num;
  let sum = 0;

  // Generate the random sequence of numbers
  while (previousNum > 1) {
    range.unshift(previousNum);
    previousNum = Math.floor(Math.random() * (previousNum - 1)) + 1;
  }

  // Calculate the sum of the numbers in the range
  for (let i = 0; i < range.length; i++) {
    sum += range[i];
  }

  return sum;
}
