function sortArray(arr) {
  // Filter out special characters and symbols from strings
  const filteredArr = arr.map((element) => {
    if (typeof element === 'string') {
      return element.replace(/[^a-zA-Z0-9]/g, '');
    }
    return element;
  });

  // Sort the filtered array in descending order
  const sortedArr = filteredArr.sort((a, b) => {
    if (typeof a === 'number' && typeof b === 'number') {
      return b - a;
    }
    return b.localeCompare(a);
  });

  // Map the sorted array back to original elements
  const result = sortedArr.map((element) => {
    const originalIndex = filteredArr.indexOf(element);
    return arr[originalIndex];
  });

  return result;
}

// Example usage
