// Selects all the images within a specified container
let images = document.querySelectorAll('.container img');

// Function to transform the coordinates of the images
function transformImages() {
  images.forEach(img => {
    // Get image's boundingClientRect
    let rect = img.getBoundingClientRect();
    let x = rect.left + rect.width / 2;
    let y = rect.top + rect.height / 2;

    // Calculate the distance from the center of the viewport
    let dx = x - window.innerWidth / 2;
