```js
class LeapYearChecker {
  constructor(startYear, endYear) {
    if(!Number.isInteger(startYear) || !Number.isInteger(endYear)) {
      throw new Error('Both start and end year must be integers.');
    }
    if(startYear > endYear) {
      throw new Error('Start year can\'t be greater than end year.');
    }
    this.startYear = startYear;
    this.endYear = endYear;
  }

  findLeapYears() {
    let leapYears = [];
    for(let year = this.startYear; year <= this.endYear; year++) {
      if(year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0)) {
        leapYears.push(year);
      }
    }
    return leapYears;
  }
}

// Let's try it out
let checker = new LeapYearChecker(2000, 2020);
console.log(checker.findLeapYears()); // [2000, 2004, 2008, 2012, 2016, 2020]
```
This code calculates leap years in O(n) time complexity taking into account every year in the specified range. Note, this code does not handle BC years or changes in the calendar (like the transition from the Julian to the Gregorian calendar in the 16th century) as historical leap years before AD 8 are inconsistent."}]

