[{"role": "assistant", "content": "Here's a JavaScript function to find the prime factors of a number:

```javascript
function primeFactors(n) {
    let factors = []; // Array to hold prime factors
    while (n % 2 === 0) { // As long as n is divisible by 2
        factors.push(2); // add 2 to factors
        n = n / 2; // then reduce n by division of 2
    }

    // n now must be odd so we start from 3 and go up
    for (let i = 3; i * i <= n; i = i + 2) {
        // as long as n is divisible by i
        while (n % i === 0) {
            factors.push(i); // add i to factors
            n = n / i; // then reduce n by division of i
        }
    }

    // If n is a prime number and n >2
    if (n > 2) {
        factors.push(n); // add n to factors
    }

    // Return the array of prime factors
    return factors;
}

console.log(primeFactors(12)); // Outputs [2, 2, 3]
```

This JavaScript function works by the principle of trial division to find the prime factors.

