```javascript
//Define the map
let map = [
  ['#', '#', '#', '#', '#', 'E'],
  ['#', '$', ' ', ' ', '#', '#'],
  ['#', '@', '#', ' ', '#', '#'],
  ['#', ' ', '#', ' ', ' ', '#'],
  ['#', '#', '#', '#', '$', '#'],
];
let xpos = 2, ypos = 1; // start position for '@'

// Function to print the game map
function print_map() {
    return map.map(row => row.join(' ')).join('\n');
}

// Function to handle movement
function move(dir) {
  map[ypos][xpos] = ' ';
  switch(dir) {
    case 'up':
      if (map[ypos - 1][xpos] !== '#') ypos--;
      break;
    case 'down':
      if (map[ypos + 1][xpos] !== '#') ypos++;
      break;
    case 'left':
      if (map[ypos][xpos - 1] !== '#') xpos--;
      break;
    case 'right':
      if (map[ypos][xpos + 1] !== '#') xpos++;
      break;
  }
  switch(map[ypos][xpos]) {
    case '$':
      console.log('You found an item!');
      break;
    case 'E':
      console.log('You reached the end!');
      return true;
  }
  map[ypos][xpos] = '@';
  return false;
}

// Function to start the game
function startGame() {
  console.log(print_map());
  var rl = require('readline').createInterface({
      input: process.stdin,
      output: process.stdout});
  rl.on('line', function(line){
      if(move(line)) rl.close();
      console.log(print_map());
  })
}
startGame();
