function jsonToHtmlTable(json) {
    let html = '<table>';
    for (let key in json) {

        if (!json.hasOwnProperty(key)) continue; // skip if key does not belongs to json
        let value = json[key];

        // Sorting an array with nested object
        if (Array.isArray(value) && typeof value[0] === 'object') {
            value.sort((a, b) => {
                let aProp = Object.keys(a).sort()[0];
                let bProp = Object.keys(b).sort()[0];
                return a[aProp] > b[bProp] ? 1 : a[aProp] < b[bProp] ? -1 : 0;
            });
        }

        html += '<tr><td>' + key + '</td><td>';

        if (value === null) {
            html += 'null';
        } else if (value === undefined) {
            html += 'undefined';
        } else if (typeof value === 'function') {
            html += 'function';
        } else if (value instanceof Date) {
            html += 'date';
        } else if (typeof value === 'object') {
            try {
                html += Array.isArray(value) ? 'array' : 'object';
                // convert nested json to table
                html += "<pre>" + jsonToHtmlTable(value) + '</pre>';
            } catch (e) {
                html += 'Circular Reference';
            }
        } else if (typeof value === 'string') {
            html += 'string: ' + value;
        } else if (typeof value === 'number') {
            html += 'number: ' + value;
        }

        html += '</td></tr>';
    }
    html += '</table>';
    return html;
}

