let array = [1,2,3,4,5];

Array.prototype.myCustomFeature = function() {
    return this.reduce((acc, val) => val % 2 !== 0 ? acc + val : acc, 0);
}

Array.prototype.sqRoot = function() {
    return this.map(val => Math.sqrt(val));
}

Array.prototype.factorial = function() {
    const factorial = (n) => n ? n * factorial(n-1) : 1;
    return this.map(val => factorial(val));
}

Array.prototype.cumSum = function() {
    let result = [];
    this.reduce((acc, val) => {
        result.push(acc + val);
        return acc + val; 
    }, 0);
    return result;
}

