// implementation of the insertion sort algorithm
function insertionSort(arr) {
    // loop through the array
    for (let i = 1; i < arr.length; i++) {
        let key = arr[i];
        let j = i - 1;

        /* 
        Move elements of arr[0..i-1], that are
        greater than key, to one position ahead
        of their current position 
        */
        while (j >= 0 && arr[j] > key) {
            arr[j + 1] = arr[j];
            j = j - 1;
        }
        arr[j + 1] = key;
    }
    return arr;
}

// function to sort even indexed elements in descending order
function sortEvenIndexed(arr) {
    let evenIndexed = arr
        .filter((_, index) => index % 2 == 0) // get the even indexed elements
        .sort((a, b) => b - a); // sort them in descending order

    // replace the even indexed elements in the original array
    for (let i = 0; i < arr.length; i += 2) {
        arr[i] = evenIndexed.shift();
    }

    return arr;
}

// use the functions
