[{"role": "assistant", "content": "```javascript
function fordFulkersonMaxFlow(graphEdges) {
  // Constructing the adjacency matrix from the graph edges
  const maxVertices = Math.max(...graphEdges.flat()) + 1;
  const adjacencyMatrix = Array.from({ length: maxVertices }, () =>
    Array(maxVertices).fill(0)
  );

  for (const edge of graphEdges) {
    const [start, end, capacity] = edge;
    adjacencyMatrix[start][end] = capacity;
  }

  function bfs(source, sink, parent) {
    const visited = Array(maxVertices).fill(false);
    const queue = [];
    queue.push(source);
    visited[source] = true;
    parent.fill(-1);

    while (queue.length !== 0) {
      const u = queue.shift();
      for (let v = 0; v < maxVertices; v++) {
        if (!visited[v] && adjacencyMatrix[u][v] > 0) {
          queue.push(v);
          parent[v] = u;
          visited[v] = true;
        }
      }
    }
    return visited[sink];
  }

  function fordFulkerson(source, sink) {
    let maxFlow = 0;
    const parent = Array(maxVertices).fill(-1);

    while (bfs(source, sink, parent)) {
      let pathFlow = Number.MAX_SAFE_INTEGER;
      for (let v = sink; v !== source; v = parent[v]) {
        const u = parent[v];
        pathFlow = Math.min(pathFlow, adjacencyMatrix[u][v]);
      }

      for (let v = sink; v !== source; v = parent[v]) {
        const u = parent[v];
        adjacencyMatrix[u][v] -= pathFlow;
        adjacencyMatrix[v][u] += pathFlow;
      }

      maxFlow += pathFlow;
    }

    return maxFlow;
  }

  // Assuming the source is 0 and the sink is the last vertex
  const source = 0;
  const sink = maxVertices - 1;

  return fordFulkerson(source, sink);
}
```"}]

