function parseStyledComponent(cssInJS) {
  const regex = /{([^}]+)}/; // Regex to match content within curly braces
  const match = cssInJS.match(regex);
  if (match) {
    const propertiesString = match[1];
    const properties = propertiesString.split(';')
      .map(prop => prop.trim())
      .filter(prop => prop !== ''); // Remove empty strings
    const extractedProperties = {};
    properties.forEach(prop => {
      const [key, value] = prop.split(':');
      extractedProperties[key.trim()] = value.trim();
    });
    return extractedProperties;
  } else {
    return {}; // Return empty object if no properties found
  }
}

