function resolveModuleImports(moduleImports) {
  const resolvedExports = {};

  for (const importStatement of moduleImports) {
    const match = importStatement.match(/export \* from "(.*?)";/);
    if (match) {
      const moduleName = match[1];
      const moduleExports = resolveModuleImports([`export * from "${moduleName}";`]);
      Object.assign(resolvedExports, moduleExports);
    } else {
      const namedExportMatch = importStatement.match(/export { (.*?)(?: as (.*?))? } from "(.*?)";/);
      if (namedExportMatch) {
        const [, exportName, alias, moduleName] = namedExportMatch;
        const moduleExports = resolveModuleImports([`export * from "${moduleName}";`]);
        const resolvedExport = alias ? { [alias]: moduleExports[exportName] } : { [exportName]: moduleExports[exportName] };
        Object.assign(resolvedExports, resolvedExport);
      }
    }
  }

  return resolvedExports;
}

